const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const vm = require("node:vm");
const { test } = require("node:test");
const {
  artifactHashes,
  parseResult,
  route,
  requireResult,
  prepare,
  verify,
} = require("./speckit-automation.cjs");

const repo = { owner: "example", repo: "broker" };
const spec = "specs/042-example";
const files = {
  [`${spec}/spec.md`]: "Feature requirements",
  [`${spec}/plan.md`]: "Technical plan",
  [`${spec}/tasks.md`]: "- [ ] T001 Implement feature",
};

function result(phase, overrides = {}) {
  return {
    phase, status: "complete", feature: spec, run: "100/1",
    files: artifactHashes(files), findings: [], questions: [],
    ...overrides,
  };
}

function comment(data, overrides = {}) {
  const workflow = ["clarify", "tasks", "remediate"].includes(data.phase) ? "phase" :
    data.phase === "reanalyze" ? "analyze" : data.phase;
  return {
    id: 11,
    issue_url: "https://api.github.com/repos/example/broker/issues/42",
    user: { login: "github-actions[bot]", type: "Bot" },
    body: `Report\n\n\`\`\`json\n${JSON.stringify(data)}\n\`\`\`\n\n> Generated by [Spec Kit Phase](https://github.com/example/broker/actions/runs/100)\n\n<!-- gh-aw-workflow-call-id: example/broker/speckit-${workflow} -->`,
    ...overrides,
  };
}

function fixture(eventName, payload, options = {}) {
  const calls = [];
  const pr = {
    number: 42, state: "open", draft: true,
    user: { login: "github-actions[bot]", type: "Bot" },
    body: "<!-- speckit-issue: 7 -->",
    head: { ref: "speckit/issue-7", sha: "a".repeat(40), repo: { full_name: "example/broker" } },
    base: { ref: "main", repo: { full_name: "example/broker" } },
    ...options.pr,
  };
  const contentReads = [];
  const github = {
    rest: {
      repos: {
        getCollaboratorPermissionLevel: async (args) => {
          calls.push(args);
          return { data: { permission: options.permission || "write" } };
        },
        getBranch: async ({ owner, repo: name, branch }) => {
          assert.equal(`${owner}/${name}`, `${repo.owner}/${repo.repo}`);
          assert.equal(branch, "speckit/issue-7");
          if (options.branchMissing || options.branchError) {
            const error = new Error("Branch lookup failed");
            error.status = options.branchError || 404;
            throw error;
          }
          return { data: { name: "speckit/issue-7" } };
        },
        getContent: async ({ path }) => {
          contentReads.push(path);
          if (path === ".specify/feature.json" && options.missingPointer) {
            const error = new Error("Not found");
            error.status = 404;
            throw error;
          }
          return {
            data: { type: "file", encoding: "base64", content: Buffer.from(
              path === ".specify/feature.json"
                ? JSON.stringify({ feature_directory: spec })
                : files[path],
            ).toString("base64") },
          };
        },
      },
      pulls: {
        get: async () => ({ data: pr }),
        list: async () => ({ data: options.existing || [] }),
      },
      issues: {
        listComments: async () => ({ data: options.comments || [] }),
        get: async () => ({ data: options.issue }),
        getComment: async ({ comment_id }) => ({ data: options.comments.find((entry) => entry.id === comment_id) }),
      },
    },
    paginate: async (method, args) => (await method(args)).data,
  };
  return {
    github, calls, contentReads,
    context: { repo, eventName, payload, actor: "maintainer", runId: 100 },
  };
}

test("specify accepts the exact issue label and does not fetch comments", async () => {
  const f = fixture("issues", { action: "labeled", label: { name: "speckit:specify" }, issue: { number: 7, state: "open" } }, { branchMissing: true });
  assert.deepEqual(await route(f), { action: "specify", issue: 7, pr: 0, comment: 0 });
  assert.equal(f.calls.length, 1);
});

test("specify requires an absent branch even without a previous PR", async () => {
  const payload = { action: "labeled", label: { name: "speckit:specify" }, issue: { number: 7, state: "open" } };
  assert.equal((await route(fixture("issues", payload))).action, "noop");
  const denied = fixture("issues", payload, { branchError: 403 });
  await assert.rejects(route(denied), (error) => error.status === 403);
});

test("unrelated labels, read-only users, bots, and issue comments do not execute", async () => {
  const cases = [
    fixture("issues", { action: "labeled", label: { name: "other" }, issue: { number: 7 } }),
    fixture("issues", { action: "labeled", label: { name: "speckit:specify" }, issue: { number: 7 } }, { permission: "read" }),
    fixture("issue_comment", { action: "created", issue: { number: 7 }, comment: { user: { type: "User" } } }),
    fixture("issue_comment", { action: "created", issue: { number: 42, pull_request: {} }, comment: { user: { type: "Bot" } } }),
  ];
  for (const f of cases) assert.equal((await route(f)).action, "noop");
});

test("relabeling a specified issue does not open another PR", async () => {
  const f = fixture("issues", { action: "labeled", label: { name: "speckit:specify" }, issue: { number: 7, state: "open" } }, { existing: [{ number: 42 }] });
  assert.equal((await route(f)).action, "noop");
});

test("relabeling resumes clarification for an existing managed PR without a clarification result", async () => {
  const issue = { number: 7, state: "open" };
  const payload = { action: "labeled", label: { name: "speckit:specify" }, issue };
  const existing = {
    number: 42, state: "open", draft: true,
    user: { login: "github-actions[bot]", type: "Bot" },
    body: "<!-- speckit-issue: 7 -->",
    head: { ref: "speckit/issue-7", repo: { full_name: "example/broker" } },
    base: { repo: { full_name: "example/broker" } },
  };
  const retry = fixture("issues", payload, { existing: [existing] });
  assert.deepEqual(await route(retry), { action: "clarify", issue: 7, pr: 42, comment: 0 });

  const completed = fixture("issues", payload, {
    existing: [existing],
    comments: [comment(result("clarify"))],
  });
  assert.equal((await route(completed)).action, "noop");

  const unmanaged = fixture("issues", payload, {
    existing: [{ ...existing, body: "unmanaged" }],
  });
  assert.equal((await route(unmanaged)).action, "noop");

  const visibleLink = fixture("issues", payload, {
    existing: [{ ...existing, body: "Related issue: https://github.com/example/broker/issues/7" }],
  });
  assert.deepEqual(await route(visibleLink), { action: "clarify", issue: 7, pr: 42, comment: 0 });
});

test("relabeling regenerates a closed Spec Kit PR only after its branch is deleted", async () => {
  const payload = { action: "labeled", label: { name: "speckit:specify" }, issue: { number: 7, state: "open" } };
  const previous = {
    number: 42, state: "closed", merged_at: null, draft: true,
    user: { login: "github-actions[bot]", type: "Bot" },
    body: "Related issue: https://github.com/example/broker/issues/7",
    head: { ref: "speckit/issue-7", repo: { full_name: "example/broker" } },
    base: { repo: { full_name: "example/broker" } },
  };
  const deleted = fixture("issues", payload, { existing: [previous], branchMissing: true });
  assert.deepEqual(await route(deleted), { action: "specify", issue: 7, pr: 0, comment: 0 });

  for (const options of [
    { existing: [previous] },
    { existing: [{ ...previous, merged_at: "2026-10-20T14:23:11Z" }], branchMissing: true },
    { existing: [{ ...previous, user: { login: "contributor", type: "User" } }], branchMissing: true },
    { existing: [{ ...previous, draft: false }], branchMissing: true },
    { existing: [{ ...previous, body: "Unrelated bot PR" }], branchMissing: true },
    { existing: [{ ...previous, head: { ...previous.head, repo: { full_name: "outsider/broker" } } }], branchMissing: true },
    { existing: [{ ...previous, head: { ...previous.head, ref: "other" } }], branchMissing: true },
    { existing: [previous, { ...previous, state: "open", body: "Unrelated bot PR" }], branchMissing: true },
  ]) {
    assert.equal((await route(fixture("issues", payload, options))).action, "noop");
  }

  const denied = fixture("issues", payload, { existing: [previous], branchError: 403 });
  await assert.rejects(route(denied), (error) => error.status === 403);
});

test("only Specify-created PRs are managed, whatever their body claims", async (t) => {
  preparationIO(t);
  const body = "<!-- speckit-issue: 7 -->\nRelated issue: https://github.com/example/broker/issues/7\n<!-- gh-aw-workflow-id: speckit-specify -->";
  for (const user of [{ login: "contributor", type: "User" }, { login: "dependabot[bot]", type: "Bot" }]) {
    const pr = { user, body };
    const relabel = fixture("issues", { action: "labeled", label: { name: "speckit:specify" }, issue: { number: 7, state: "open" } }, {
      existing: [{
        number: 42, state: "open", draft: true, ...pr,
        head: { ref: "speckit/issue-7", repo: { full_name: "example/broker" } },
        base: { repo: { full_name: "example/broker" } },
      }],
    });
    assert.deepEqual(await route(relabel), { action: "noop" });
    const planning = fixture("pull_request_target", { action: "labeled", label: { name: "speckit:plan-execution" }, pull_request: { number: 42 } }, {
      pr, comments: [comment(result("clarify"))],
    });
    assert.deepEqual(await route(planning), { action: "noop" });
    await assert.rejects(prepare({ ...fixture("pull_request_target", {}, { pr }), inputs: { phase: "clarify", pr: 42 } }), /managed/);
  }
});

test("only maintainer comments posted after pending questions become answers", async () => {
  const payload = {
    action: "created", issue: { number: 42, pull_request: {} },
    comment: { id: 20, body: "1. Option A", user: { login: "maintainer", type: "User" } },
  };
  const pending = comment(result("clarify", { status: "waiting", questions: ["Which users can access the feature?"] }));
  const f = fixture("issue_comment", payload, { comments: [pending] });
  assert.deepEqual(await route(f), { action: "clarify", issue: 7, pr: 42, comment: 20 });
  const old = fixture("issue_comment", { ...payload, comment: { ...payload.comment, id: 10 } }, { comments: [pending] });
  assert.equal((await route(old)).action, "noop");
  const read = fixture("issue_comment", payload, { permission: "read", comments: [pending] });
  assert.equal((await route(read)).action, "noop");
  const complete = fixture("issue_comment", payload, { comments: [comment(result("clarify"))] });
  assert.equal((await route(complete)).action, "noop");
});

test("invalid historical results do not hide later clarification questions", async () => {
  const invalid = comment(result("clarify"), { id: 10 });
  invalid.body = invalid.body.replace(JSON.stringify(result("clarify")), '{"example":true}');
  const pending = comment(result("clarify", {
    status: "waiting", questions: ["Which command is supported?"],
  }));
  const answer = { id: 20, body: "Q1: A", user: { login: "maintainer", type: "User" } };
  const f = fixture("issue_comment", {
    action: "created", issue: { number: 42, pull_request: {} }, comment: answer,
  }, { comments: [invalid, pending] });
  assert.deepEqual(await route(f), { action: "clarify", issue: 7, pr: 42, comment: 20 });
});

test("a published waiting clarification can receive a maintainer answer without permitting planning", async (t) => {
  preparationIO(t);
  const pending = comment(result("clarify", { status: "waiting", questions: ["Which command is supported?"] }));
  const answer = { id: 20, issue_url: pending.issue_url, body: "Q1: A", user: { login: "maintainer", type: "User" } };
  const f = fixture("issue_comment", {
    action: "created", issue: { number: 42, pull_request: {} }, comment: answer,
  }, { comments: [pending, answer] });
  assert.deepEqual(await route(f), { action: "clarify", issue: 7, pr: 42, comment: 20 });
  const prepared = await prepare({ ...f, inputs: { phase: "clarify", pr: 42, comment: 20 } });
  assert.deepEqual(prepared.answer, { id: 20, body: "Q1: A", author: "maintainer" });
  assert.equal((await verify({ ...f, comment: 11, phase: "clarify" })).status, "waiting");
  await assert.rejects(route(fixture("pull_request_target", {
    action: "labeled", label: { name: "speckit:plan-execution" }, pull_request: { number: 42 },
  }, { comments: [pending] })), /waiting/);
});

