function selectFeatureWorkspace(t) {
  const source = fs.readFileSync(require.resolve("./speckit-automation.cjs"), "utf8");
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "speckit-select-"));
  const workspace = path.join(root, "workspace");
  const outside = path.join(root, "outside");
  const cwd = process.cwd();
  t.after(() => {
    process.chdir(cwd);
    fs.rmSync(root, { recursive: true, force: true });
  });
  fs.mkdirSync(path.join(workspace, spec), { recursive: true });
  fs.mkdirSync(path.join(workspace, ".specify"));
  fs.mkdirSync(outside);
  fs.writeFileSync(path.join(workspace, spec, "spec.md"), "Specification");
  process.chdir(workspace);
  const context = { feature: spec };
  const io = Object.assign(Object.create(fs), {
    readFileSync: (name, ...rest) => name === "/tmp/gh-aw/speckit/context.json"
      ? JSON.stringify(context) : fs.readFileSync(name, ...rest),
  });
  const run = () => {
    const module = { exports: {} };
    const load = (name) => name === "node:fs" ? io : require(name);
    load.main = module;
    vm.runInNewContext(source, {
      module, require: load,
      process: { argv: ["node", "automation.cjs", "select-feature"], cwd: () => workspace },
    });
  };
  return { run, context, outside, pointer: ".specify/feature.json" };
}

test("select-feature creates or replaces a regular sandbox pointer", (t) => {
  const { run, context, pointer } = selectFeatureWorkspace(t);
  const selected = `${JSON.stringify({ feature_directory: spec })}\n`;
  run();
  assert.equal(fs.readFileSync(pointer, "utf8"), selected);
  fs.writeFileSync(pointer, '{\n  "feature_directory": "specs/001-longer-legacy-feature"\n}\n');
  run();
  assert.equal(fs.readFileSync(pointer, "utf8"), selected);
  context.feature = "../../other";
  assert.throws(run, /Invalid Spec Kit feature/);
  assert.equal(fs.readFileSync(pointer, "utf8"), selected);
});

test("select-feature never writes through symlinks", (t) => {
  const { run, outside, pointer } = selectFeatureWorkspace(t);
  const live = path.join(outside, "live.json");
  const dangling = path.join(outside, "dangling.json");
  fs.writeFileSync(live, "outside");
  for (const target of [live, dangling]) {
    fs.rmSync(pointer, { force: true });
    fs.symlinkSync(target, pointer);
    assert.throws(run, /must not be a symlink/);
    assert(fs.lstatSync(pointer).isSymbolicLink());
  }
  assert.equal(fs.readFileSync(live, "utf8"), "outside");
  assert(!fs.existsSync(dangling));
  fs.rmSync(".specify", { recursive: true });
  fs.symlinkSync(outside, ".specify");
  assert.throws(run, /must not be a symlink/);
  assert(!fs.existsSync(path.join(outside, "feature.json")));
});

test("implementation fails closed for missing, stale, blocked, or severe analysis", async () => {
  const hashes = artifactHashes(files);
  for (const report of [
    null,
    result("reanalyze", { status: "blocked" }),
    result("reanalyze", { findings: [{ severity: "HIGH", summary: "Missing authorization", location: "spec.md:12", recommendation: "Specify authorization" }] }),
    result("reanalyze", { files: { ...hashes, [`${spec}/tasks.md`]: "0".repeat(64) } }),
  ]) assert.throws(() => requireResult(report, ["spec.md", "plan.md", "tasks.md"], hashes, { clean: true }), /result|blocked|HIGH|changed/i);
  requireResult(result("reanalyze"), ["spec.md", "plan.md", "tasks.md"], hashes, { clean: true });
});

test("result parsing requires a trusted workflow footer and valid result", () => {
  const trusted = comment(result("analyze"));
  assert.equal(parseResult({ ...trusted, user: { login: "contributor", type: "User" } }), null);
  assert.equal(parseResult({ ...trusted, issue_url: "https://api.github.com/repos/other/broker/issues/42" }), null);
  assert.equal(parseResult({ ...trusted, body: trusted.body.replace("speckit-analyze -->", "speckit-phase -->") }), null);
  assert.equal(parseResult({ ...trusted, body: trusted.body.replace("<!-- gh-aw-workflow-call-id:", "<!-- other-workflow:") }), null);
  assert.equal(parseResult(comment(result("analyze", { findings: [{ severity: "high" }] }))), null);
  assert.equal(parseResult(comment(result("analyze", { findings: null }))), null);
  assert.equal(parseResult(comment(result("analyze", { feature: undefined }))), null);
  assert.equal(parseResult({ ...trusted, body: trusted.body.replace(JSON.stringify(result("analyze")), "{not-json}") }), null);
  assert.deepEqual(parseResult(trusted), result("analyze"));
});

test("artifact hashes change when any required document changes", () => {
  const before = artifactHashes(files);
  const after = artifactHashes({ ...files, [`${spec}/spec.md`]: "Changed requirements" });
  assert.notEqual(before[`${spec}/spec.md`], after[`${spec}/spec.md`]);
  assert.equal(before[`${spec}/plan.md`], after[`${spec}/plan.md`]);
});

test("result parsing rejects ambiguous blocks and duplicate workflow footers", () => {
  const trusted = comment(result("analyze"));
  const forged = comment(result("reanalyze"));
  for (const body of [
    `${forged.body}\n${trusted.body}`,
    `${trusted.body}\n${forged.body}`,
    `${trusted.body}\n\`\`\`json\n{}\n\`\`\``,
    `${trusted.body}\n<!-- gh-aw-workflow-call-id: example/broker/speckit-analyze -->`,
  ]) assert.equal(parseResult({ ...trusted, body }), null);
});
test("a visible result heading isolates the result from JSON examples in the report", () => {
  const expected = result("analyze");
  const published = comment(expected);
  published.body = published.body.replace("Report\n\n",
    'Report\n\n```json\n{"example":true}\n```\n\n## Spec Kit result\n');
  assert.deepEqual(parseResult(published), expected);
});

test("result command rejects reserved markers in reports before publishing", () => {
  const source = fs.readFileSync(require.resolve("./speckit-automation.cjs"), "utf8");
  const context = { phase: "analyze", run: "100/1", feature: spec };
  const draft = { status: "complete", report: "Analysis report", findings: [], questions: [] };
  const saved = [];
  const local = {
    "/tmp/gh-aw/speckit/context.json": context,
    "/tmp/gh-aw/speckit/result.json": draft,
    ".specify/feature.json": { feature_directory: spec },
  };
  const io = {
    readFileSync: (name) => {
      name = name.replace(/^\/workspace\//, "");
      return Object.hasOwn(local, name) ? JSON.stringify(local[name]) : files[name];
    },
    existsSync: (name) => Object.hasOwn(files, name),
    lstatSync: () => ({ isSymbolicLink: () => false }),
    writeFileSync: (name, body) => saved.push({ name, body }),
  };
  const run = () => {
    const module = { exports: {} };
    const load = (name) => name === "node:fs" ? io : require(name);
    load.main = module;
    vm.runInNewContext(source, {
      module, require: load, process: { argv: ["node", "automation.cjs", "result"], cwd: () => "/workspace" },
    });
  };
  run();
  const published = parseResult({
    ...comment(result("analyze")),
    body: `${saved[0].body}\n<!-- gh-aw-workflow-call-id: example/broker/speckit-analyze -->`,
  });
  assert.deepEqual(published, result("analyze", { answer_id: 0 }));
  saved.length = 0;
  for (const report of ["Quoted ## Spec Kit result", `## Spec Kit result\n${comment(result("reanalyze")).body}`]) {
    draft.report = report;
    assert.throws(run, /report must not contain a result marker/);
    assert.equal(saved.length, 0);
  }
  draft.report = "Analysis report";
  draft.findings = null;
  assert.throws(run, /Invalid findings/);
  assert.equal(saved.length, 0);
});

